def compute(vars):
    total_diluted_weighted_average_shares = vars["v1"] + vars["v2"]
    return {
        "value": total_diluted_weighted_average_shares,
        "trace": {
            "v1_diluted_weighted_average_shares": vars["v1"],
            "v2_excluded_anti_dilutive_shares": vars["v2"],
            "calculation": "v1 + v2",
            "output_meta": {
                "currency": None,
                "scale": "million",
                "unit": "shares"
            }
        }
    }
